const item = $input.item.json;
const reqText = item.requirement || '';

const prompt = `Bạn là Chuyên gia Kiến trúc Phần mềm và AI Phân tích Yêu cầu Agile (Senior Product Owner / Business Analyst).

Nhiệm vụ: Phân tích sâu sắc văn bản đặc tả yêu cầu phần mềm dưới đây và bóc tách thành Cây phân cấp Agile chuẩn mực 3 tầng:
1. Epic: Phân hệ / Tính năng lớn cấp cao (High-level Module/Feature).
2. User Story: Câu chuyện người dùng theo mẫu "Là [Người dùng], tôi muốn [Hành động] để [Mục đích / Giá trị]" hoặc tiêu đề súc tích, kèm mô tả đặc tả chức năng chi tiết.
   ĐẶC BIỆT: Mỗi User Story BẮT BUỘC có danh sách "acceptance_criteria" (Tiêu chí nghiệm thu / chấp nhận) viết theo chuẩn BDD (Given - When - Then) rõ ràng, cụ thể (tối thiểu 2 tiêu chí cho mỗi Story).
3. Task: Các đầu việc kỹ thuật cụ thể (Frontend, Backend, Database, Test, DevOps) để hoàn thành Story đó.

YÊU CẦU BẮT BUỘC:
1. Chỉ trả về một đối tượng JSON DUY NHẤT, không có bất kỳ chữ nào khác ngoài JSON.
2. Tuyệt đối KHÔNG bọc JSON trong khối mã markdown (KHÔNG dùng \`\`\`json hoặc \`\`\`).
3. Cấu trúc JSON chuẩn mực phải khớp chính xác 100%:
{
  "epics": [
    {
      "title": "Tên Epic",
      "description": "Mô tả mục tiêu của Epic",
      "stories": [
        {
          "title": "Tên Story",
          "description": "Mô tả chi tiết Story",
          "acceptance_criteria": [
            "Given [điều kiện tiền đề], When [hành động của người dùng], Then [kết quả mong đợi]",
            "Given [tình huống kiểm thử hoặc ngoại lệ], When [xảy ra], Then [hệ thống xử lý an toàn]"
          ],
          "tasks": [
            {
              "title": "Tên Task kỹ thuật",
              "description": "Mô tả công việc kỹ thuật cần triển khai"
            }
          ]
        }
      ]
    }
  ]
}

VĂN BẢN ĐẶC TẢ YÊU CẦU:
"${reqText}"`;

return {
  json: {
    ...item,
    prompt: prompt
  }
};

const item = $input.item.json;

// 1. Trích xuất text thô chính xác từ cây cấu trúc của Gemini
let raw = '';
if (item.content?.parts?.[0]?.text) {
  raw = item.content.parts[0].text;
} else if (item.parts?.[0]?.text) {
  raw = item.parts[0].text;
} else if (item.candidates?.[0]?.content?.parts?.[0]?.text) {
  raw = item.candidates[0].content.parts[0].text;
} else if (typeof item.content === 'string') {
  raw = item.content;
} else if (item.text) {
  raw = item.text;
} else if (item.response?.text) {
  raw = item.response.text;
} else {
  raw = JSON.stringify(item);
}

// 2. Làm sạch markdown ```json
let cleanText = String(raw).trim().replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();

let parsed = null;
let isValidSchema = false;
let schemaErrorDetails = '';

try {
  parsed = JSON.parse(cleanText);
} catch (err) {
  const firstBrace = cleanText.indexOf('{');
  const lastBrace = cleanText.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace > firstBrace) {
    try {
      parsed = JSON.parse(cleanText.substring(firstBrace, lastBrace + 1));
    } catch (innerErr) {
      schemaErrorDetails = 'Lỗi parse JSON: ' + err.message;
    }
  } else {
    schemaErrorDetails = 'Không tìm thấy JSON: ' + err.message;
  }
}

// 3. Chuẩn hóa mảng epics
let sanitizedEpics = [];
let totalStories = 0;
let totalTasks = 0;

if (parsed) {
  let epics = parsed.epics || parsed.Epics || parsed.modules || (Array.isArray(parsed) ? parsed : null);
  if (epics && !Array.isArray(epics) && typeof epics === 'object') {
    epics = Object.values(epics);
  }

  if (Array.isArray(epics) && epics.length > 0) {
    sanitizedEpics = epics.map((epic, ei) => {
      const title = String(epic.title || epic.name || `Epic #${ei + 1}`).trim();
      const description = String(epic.description || epic.desc || '').trim();
      const rawStories = epic.stories || epic.user_stories || [];

      const sanitizedStories = (Array.isArray(rawStories) ? rawStories : Object.values(rawStories || {})).map((story, si) => {
        const sTitle = String(story.title || story.name || `Story #${si + 1}`).trim();
        const sDesc = String(story.description || story.desc || '').trim();

        // Trích xuất Acceptance Criteria (Tiêu chí nghiệm thu BDD)
        const rawAc = story.acceptance_criteria || story.acceptanceCriteria || story.criteria || [];
        const sanitizedAc = (Array.isArray(rawAc) ? rawAc : [rawAc])
          .filter(Boolean)
          .map((ac) => typeof ac === 'string' ? ac.trim() : String(ac.text || ac.title || JSON.stringify(ac)).trim())
          .filter((text) => text.length > 0);

        const rawTasks = story.tasks || story.subtasks || [];

        const sanitizedTasks = (Array.isArray(rawTasks) ? rawTasks : Object.values(rawTasks || {})).map((task, ti) => {
          if (typeof task === 'string') return { title: task.trim(), description: '' };
          return {
            title: String(task.title || task.name || `Task #${ti + 1}`).trim(),
            description: String(task.description || task.desc || '').trim()
          };
        });

        totalTasks += sanitizedTasks.length;
        return {
          title: sTitle,
          description: sDesc,
          acceptance_criteria: sanitizedAc,
          acceptanceCriteria: sanitizedAc,
          tasks: sanitizedTasks
        };
      });

      totalStories += sanitizedStories.length;
      return { title: title, description: description, stories: sanitizedStories };
    });

    isValidSchema = true;
  } else {
    schemaErrorDetails = 'Thiếu mảng epics hợp lệ';
  }
}

// 4. Trả về kết quả
if (isValidSchema) {
  return {
    json: {
      success: true,
      isValidSchema: true,
      epics: sanitizedEpics,
      metadata: {
        totalEpics: sanitizedEpics.length,
        totalStories: totalStories,
        totalTasks: totalTasks,
        model: 'models/gemini-3.1-flash-lite'
      }
    }
  };
} else {
  return {
    json: {
      isValidSchema: false,
      schemaErrorDetails: schemaErrorDetails,
      rawOutput: cleanText.slice(0, 300)
    }
  };
}
